'use strict';

// MODULES //

var Uint32Array = require( '@stdlib/array-uint32' );
var isBetween = require( '@stdlib/assert-is-between' );
var isInteger = require( '@stdlib/assert-is-integer' ).isPrimitive;
var isString = require( '@stdlib/assert-is-string' ).isPrimitive;
var isEmptyString = require( '@stdlib/assert-is-empty-string' ).isPrimitive;
var string2words = require( '@stdlib/number-uint64-base-string2words' ).assign;
var Uint64 = require( '@stdlib/number-uint64-ctor' );
var ltrim = require( '@stdlib/string-base-left-trim' );
var lowercase = require( '@stdlib/string-base-lowercase' );
var slice = require( '@stdlib/string-base-slice' );
var trim = require( '@stdlib/string-base-trim' );
var format = require( '@stdlib/string-format' );


// VARIABLES //

var RE_HEX = /^0x/;
var RE_BIN = /^0b/;
var RE_OCT = /^0o/;
var DIGITS = '0123456789abcdefghijklmnopqrstuvwxyz';
var WORKSPACE = new Uint32Array( 2 );


// FUNCTIONS //

/**
* Returns a regular expression that matches any character that is not a valid digit in the number system of the given radix.
*
* @private
* @param {PositiveInteger} radix - radix (base) of the number system (2-36)
* @returns {RegExp} regular expression
*
* @example
* var v = regexp( 10 );
* // returns /[^0123456789]/
*
* v = regexp( 16 );
* // returns /[^0123456789abcdef]/
*
*/
function regexp( radix ) {
	var validDigits = slice( DIGITS, 0, radix );
	return new RegExp( format( '[^%s]', validDigits ) );
}


// MAIN //

/**
* Parses a string representation of a 64-bit unsigned integer.
*
* @param {string} str - string representation of a 64-bit unsigned integer
* @param {PositiveInteger} radix - radix (base) to use for string conversion (2-36)
* @throws {TypeError} first argument must be a string
* @throws {SyntaxError} first argument must be a string encoding a nonnegative integer
* @throws {RangeError} first argument must be a string encoding a nonnegative integer on the interval [0, 2^64-1]
* @throws {TypeError} second argument must be an integer
* @throws {RangeError} second argument must be an integer on the interval [2, 36]
* @returns {Uint64} 64-bit unsigned integer
*
* @example
* var a = parseUint64( '1234' );
* // returns <Uint64>[ 1234n ]
*
* a = parseUint64( '0xffffffffffffffff' );
* // returns <Uint64>[ 18446744073709551615n ]
*
* a = parseUint64( '123abcxyz', 36 );
* // returns <Uint64>[ 2984992324091n ]
*/
function parseUint64( str, radix ) {
	var rad;
	var s;
	var i;

	if ( !isString( str ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be a string. Value: `%s`.', str ) );
	}

	s = trim( str );
	if ( s[ 0 ] === '-' ) {
		throw new SyntaxError( format( 'invalid argument. First argument must be a string encoding a nonnegative integer. Value: `%s`.', str ) );
	}

	// Trim optional plus sign and following whitespace:
	if ( s[ 0 ] === '+' ) {
		s = ltrim( slice( s, 1, s.length ) );
	}

	// Convert to lowercase:
	s = lowercase( s );

	if ( arguments.length < 2 ) {
		if ( RE_BIN.test( s ) ) {
			rad = 2;
		} else if ( RE_OCT.test( s ) ) {
			rad = 8;
		} else if ( RE_HEX.test( s ) ) {
			rad = 16;
		} else {
			rad = 10;
		}

		if ( rad !== 10 ) {
			s = slice( s, 2 ); // remove the radix prefix
		}
	} else if ( !isInteger( radix ) ) {
		throw new TypeError( format( 'invalid argument. Second argument must be an integer. Value: `%s`.', radix ) );
	} else if ( isBetween( radix, 2, 36 ) ) {
		rad = radix;
	} else {
		throw new RangeError( format( 'invalid argument. Second argument must be an integer on the interval [2, 36]. Value: `%s`.', radix ) );
	}

	// Handles cases such as '', ' ', '0x':
	if ( isEmptyString( s ) ) {
		throw new SyntaxError( format( 'invalid argument. First argument must be a string encoding a nonnegative integer. Value: `%s`.', str ) );
	}

	// Trim leading zeros:
	i = 0;
	while ( ( i < s.length-1 ) && ( s[ i ] === '0' ) ) {
		i += 1;
	}
	s = slice( s, i, s.length );

	// Validate digits with respect to the radix:
	if ( regexp( rad ).test( s ) ) {
		throw new SyntaxError( format( 'invalid argument. First argument must be a string encoding a nonnegative integer. Value: `%s`.', str ) );
	}

	try {
		string2words( s, rad, WORKSPACE, 1, 0 );
	} catch ( err ) {
		if ( err instanceof RangeError ) {
			throw new RangeError( format( 'invalid argument. First argument must be a string encoding a nonnegative integer on the interval [0, 2^64-1]. Value: `%s`.', str ) );
		}
		throw err;
	}

	return Uint64.of( WORKSPACE[ 0 ], WORKSPACE[ 1 ] );
}


// EXPORTS //

module.exports = parseUint64;
